//! Linguist's default exclusions: vendored code, generated files and documentation do not
//! describe what a repository is written in. `.gitattributes` can override each of them.

/// Directory names that hold third-party or build output at any depth.
const VENDORED_DIRECTORIES: &[&str] = &[
    "node_modules",
    "bower_components",
    "vendor",
    "vendors",
    "third_party",
    "third-party",
    "thirdparty",
    "3rdparty",
    "dist",
    "build",
    "Pods",
    "Carthage",
];

/// File-name suffixes of minified or bundled assets.
const VENDORED_SUFFIXES: &[&str] = &[".min.js", ".min.css", ".min.mjs", "-min.js", ".bundle.js"];

/// Lockfiles and other machine-written files, by exact name.
const GENERATED_FILENAMES: &[&str] = &[
    "Cargo.lock",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "yarn.lock",
    "pnpm-lock.yaml",
    "bun.lockb",
    "bun.lock",
    "deno.lock",
    "go.sum",
    "poetry.lock",
    "Pipfile.lock",
    "uv.lock",
    "pdm.lock",
    "composer.lock",
    "Gemfile.lock",
    "mix.lock",
    "flake.lock",
    "Package.resolved",
    "pubspec.lock",
    "packages.lock.json",
    "gradle.lockfile",
];

/// File-name suffixes of generated sources.
const GENERATED_SUFFIXES: &[&str] =
    &[".pb.go", "_pb2.py", "_pb2_grpc.py", ".pb.cc", ".pb.h", ".designer.cs", ".g.dart", ".freezed.dart", ".js.map", ".css.map"];

/// Directories holding documentation at the repository root.
const ROOT_DOCUMENTATION_DIRECTORIES: &[&str] = &["docs", "doc", "Docs", "Doc"];

/// Directories holding documentation at any depth.
const DOCUMENTATION_DIRECTORIES: &[&str] = &["Documentation", "documentation", "javadoc", "groovydoc"];

/// Vendored by default: dependency directories, build output, minified assets and any
/// `.git*` path (`.github/`, `.gitignore`, …).
pub fn is_vendored(path: &str) -> bool {
    let mut segments = path.split('/').peekable();
    while let Some(segment) = segments.next() {
        let is_directory = segments.peek().is_some();
        if segment.starts_with(".git") || (is_directory && VENDORED_DIRECTORIES.contains(&segment)) {
            return true;
        }
    }
    let name = file_name(path);
    VENDORED_SUFFIXES.iter().any(|suffix| name.ends_with(suffix))
}

/// Generated by default: lockfiles and well-known code generator outputs.
pub fn is_generated(path: &str) -> bool {
    let name = file_name(path);
    GENERATED_FILENAMES.contains(&name) || GENERATED_SUFFIXES.iter().any(|suffix| name.ends_with(suffix))
}

/// Documentation by default: `docs/` or `doc/` at the root, `Documentation/` anywhere.
pub fn is_documentation(path: &str) -> bool {
    let Some((directories, _)) = path.rsplit_once('/') else { return false };
    let mut segments = directories.split('/');
    let first = segments.next().unwrap_or_default();
    ROOT_DOCUMENTATION_DIRECTORIES.contains(&first)
        || DOCUMENTATION_DIRECTORIES.contains(&first)
        || segments.any(|segment| DOCUMENTATION_DIRECTORIES.contains(&segment))
}

/// Whether nothing below `directory` can count by default, so the walk may skip it.
pub fn is_excluded_directory(directory: &str) -> bool {
    // Probe with a placeholder file inside the directory.
    let probe = format!("{directory}/_");
    is_vendored(&probe) || is_documentation(&probe)
}

fn file_name(path: &str) -> &str {
    path.rsplit_once('/').map_or(path, |(_, name)| name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn vendored_paths() {
        assert!(is_vendored("node_modules/react/index.js"));
        assert!(is_vendored("web/node_modules/x.js"));
        assert!(is_vendored("vendor/github.com/x/y.go"));
        assert!(is_vendored("third_party/zlib/inflate.c"));
        assert!(is_vendored("dist/app.js"));
        assert!(is_vendored("build/out.js"));
        assert!(is_vendored(".github/workflows/ci.yml"));
        assert!(is_vendored(".gitignore"));
        assert!(is_vendored("static/jquery.min.js"));
        assert!(is_vendored("static/site.min.css"));
        assert!(!is_vendored("src/main.rs"));
        assert!(!is_vendored("src/build.rs"), "a file named like a vendored directory is not vendored");
        assert!(!is_vendored("src/distance.rs"));
    }

    #[test]
    fn generated_paths() {
        assert!(is_generated("Cargo.lock"));
        assert!(is_generated("web/package-lock.json"));
        assert!(is_generated("yarn.lock"));
        assert!(is_generated("pnpm-lock.yaml"));
        assert!(is_generated("go.sum"));
        assert!(is_generated("poetry.lock"));
        assert!(is_generated("composer.lock"));
        assert!(is_generated("api/service.pb.go"));
        assert!(!is_generated("Cargo.toml"));
    }

    #[test]
    fn documentation_paths() {
        assert!(is_documentation("docs/index.html"));
        assert!(is_documentation("doc/guide/intro.rs"));
        assert!(is_documentation("kernel/Documentation/conf.py"));
        assert!(!is_documentation("src/docs/mod.rs"), "only root docs/ is documentation");
        assert!(!is_documentation("docs.rs"));
        assert!(is_excluded_directory("docs"));
        assert!(is_excluded_directory("a/node_modules"));
        assert!(!is_excluded_directory("src"));
    }
}
